<?php

declare(strict_types=1); namespace App\Tools\RetroactiveDasRegularizationCalculator\Tests\Unit; use App\Tools\RetroactiveDasRegularizationCalculator\Application\Data\CalculationInput; use App\Tools\RetroactiveDasRegularizationCalculator\Domain\Services\Calculator; use PHPUnit\Framework\TestCase; final class CalculatorTest extends TestCase { public function test_estimates_principal_fine_interest_and_total():void{$r=(new Calculator())->calculate(new CalculationInput([['competence'=>'2026-06','revenue'=>'20.000,00','effective_rate'=>'6','due_date'=>'2026-07-20','update_date'=>'2026-08-12','accumulated_selic'=>'1,12']],6));self::assertSame(120000,$r->details['competencies'][0]['principal_minor']);self::assertGreaterThan(120000,$r->details['competencies'][0]['total_minor']);self::assertCount(6,$r->details['regularization']['schedule']);} public function test_consolidates_multiple_competencies():void{$r=(new Calculator())->calculate(new CalculationInput([['competence'=>'2026-05','revenue'=>'10.000,00','effective_rate'=>'6','due_date'=>'2026-06-20','update_date'=>'2026-08-12','accumulated_selic'=>'2'],['competence'=>'2026-06','revenue'=>'20.000,00','effective_rate'=>'6','due_date'=>'2026-07-20','update_date'=>'2026-08-12','accumulated_selic'=>'1']],3));self::assertSame(180000,$r->details['consolidated']['principal_minor']);self::assertCount(2,$r->details['competencies']);}}
